// A. Watch what people cannot explain; ask many people the same thing with a questionnaire; read systems and documents.
const TECHNIQUES = {
  S1: 'Observation',
  S2: 'Questionnaire',
  S3: 'System interface analysis',
  S4: 'Prototyping',
  S5: 'Workshop',
  S6: 'Document analysis',
  S7: 'Focus group',
  S8: 'Interview',
  S9: 'User interface analysis',
};

// B. Prepare (scope, agenda, participants, questions, invitation) → perform (facilitate, stay in scope, take notes) → follow up (notes, open issues, classify input).
const PHASES = {
  T1: 'PREPARE',
  T2: 'PREPARE',
  T3: 'PERFORM',
  T4: 'PERFORM',
  T5: 'FOLLOW_UP',
  T6: 'FOLLOW_UP',
  T7: 'FOLLOW_UP',
  T8: 'PREPARE',
};

// D. Open = invites a description; closed = a fact or a choice; leading = suggests the answer the BA wants to hear.
const QUESTIONS = {
  Q1: 'OPEN',
  Q2: 'CLOSED',
  Q3: 'LEADING',
  Q4: 'OPEN',
  Q5: 'LEADING',
  Q6: 'CLOSED',
};

// E. Wiegers: no new use cases, new scenarios are variations, new ideas are out of scope or low priority. Budget and deadline are not evidence.
const DONE_SIGNALS = ['a', 'c', 'e'];
// The button is a solution idea; the need is to pay quickly from any screen.
const REAL_NEED_C9 = 'PAY_QUICKLY';

